function validate([s]) {
  if (typeof s !== 'string' || s.length < 4 || s.length > 12) return 's needs 4 to 12 characters.';
  if (!/^\([0-9]+\)$/.test(s)) return 's must be "(" then only digits then ")".';
  return null;
}

