function ambiguousCoordinates(s) {
  const digits = s.slice(1, -1);
  const readings = (part) => {
    const found = [];
    for (let cut = 1; cut <= part.length; cut++) {
      const whole = part.slice(0, cut);
      const fraction = part.slice(cut);
      if (whole.length > 1 && whole[0] === '0') break;
      if (fraction.endsWith('0')) continue;
      found.push(fraction === '' ? whole : `${whole}.${fraction}`);
    }
    return found;
  };
  const result = [];
  for (let split = 1; split < digits.length; split++) {
    const xs = readings(digits.slice(0, split));
    const ys = readings(digits.slice(split));
    for (const x of xs) {
      for (const y of ys) {
        result.push(`(${x}, ${y})`);
      }
    }
  }
  return result;
}

