function ambiguousCoordinates(s) {
  // Try every comma and every point position (including none and the ends), then keep the well-formed numbers.
  const digits = s.slice(1, -1);
  const shortest = /^(0|[1-9][0-9]*)(\.[0-9]*[1-9])?$/;
  const withPoint = (part) => {
    const list = [part];
    for (let i = 0; i <= part.length; i++) list.push(part.slice(0, i) + '.' + part.slice(i));
    return list;
  };
  const out = [];
  for (let i = 1; i < digits.length; i++)
    for (const x of withPoint(digits.slice(0, i)))
      for (const y of withPoint(digits.slice(i)))
        if (shortest.test(x) && shortest.test(y)) out.push('(' + x + ', ' + y + ')');
  return out;
}

