function generate(rand, size) {
  const n = size === 'large' ? 8 + Math.floor(rand() * 3) : 2 + Math.floor(rand() * 5);
  // Zeros are what make readings invalid, so use them often.
  const zeroBias = rand() * 0.7;
  let digits = '';
  for (let i = 0; i < n; i++) digits += rand() < zeroBias ? '0' : String(Math.floor(rand() * 10));
  return ['(' + digits + ')'];
}
